		const NUMBER_STYLE = { width: "60px", padding: "3px 6px", fontSize: "12px", fontVariantNumeric: "tabular-nums", textAlign: "right", color: "var(--dsw-alias-label-primary)", background: "var(--dsw-alias-bg-layer-2)", border: "1px solid var(--dsw-alias-border-l2)" };
		const UNIT_STYLE = { fontSize: "12px", color: "var(--dsw-alias-label-caption)", width: "16px" };

		/** 与拉条双向同步的数值框：输入过程中不提交，失焦或回车才夹到范围并写回。 */
